#!/usr/bin/env python3
"""page-source-check scanner.

사용:
  python3 scan.py https://example.com          # 누구나 볼 수 있는 소스만 점검
  python3 scan.py https://example.com --own    # 내 사이트: 설정 파일 노출, Supabase 읽기 권한까지 확인
  python3 scan.py ./dist                       # 배포 전 폴더 점검

표준 라이브러리만 쓴다. 결과는 마크다운 표로 출력하고, 비밀키는 앞 4자리만 보여 준다.
"""
import base64
import json
import os
import re
import sys
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

UA = "Mozilla/5.0 (page-source-check)"
MAX_PAGES = 20
MAX_ASSETS = 40
TIMEOUT = 15

# ---------- 찾을 것 ----------
SECRET_PATTERNS = [
    ("OpenAI 키", re.compile(r"(?<![A-Za-z0-9_\-])sk-(?:proj|svcacct|admin)-[A-Za-z0-9_\-]{40,}|(?<![A-Za-z0-9_\-])sk-[A-Za-z0-9]{20}T3BlbkFJ[A-Za-z0-9]{20}")),
    ("Anthropic 키", re.compile(r"(?<![A-Za-z0-9_\-])sk-ant-(?:api|admin)\d\d-[A-Za-z0-9_\-]{60,}")),
    ("Stripe 비밀키", re.compile(r"(?:sk|rk)_live_[A-Za-z0-9]{16,}")),
    ("AWS 키", re.compile(r"AKIA[0-9A-Z]{16}")),
    ("GitHub 토큰", re.compile(r"gh[pousr]_[A-Za-z0-9]{30,}")),
    ("Slack 토큰", re.compile(r"xox[baprs]-[A-Za-z0-9\-]{10,}")),
]
PASSWORD = re.compile(r"""(?i)\b(?:password|passwd|pwd|비번|비밀번호)\s*[:=]\s*["']([^"'\s]{6,})["']""")
PASSWORD_FAKE = re.compile(r"(?i)^(password|passwd|pwd|\*+|x+|placeholder|current-password|new-password|text|string|hidden|required|.*\$\{.*)$")
GOOGLE_KEY = re.compile(r"AIza[0-9A-Za-z_\-]{35}")
JWT = re.compile(r"eyJ[A-Za-z0-9_\-]{10,}\.eyJ[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}")
SUPABASE_URL = re.compile(r"https://[a-z0-9]{10,40}\.supabase\.co")
SUPABASE_NEWKEY = re.compile(r"sb_(secret|publishable)_[A-Za-z0-9_\-]{10,}")

PHONE = re.compile(r"(?<![\d\-.])(?:\+82[-.\s]?|0)1[016789]([-.\s])\d{3,4}\1\d{4}(?![\d\-.])")
PHONE_FAKE = re.compile(r"(0000|1234[-.\s]5678|1111|9999|xxxx)")
RRN = re.compile(r"\b\d{6}-[1-4]\d{6}\b")
EMAIL = re.compile(r"[A-Za-z0-9._%+\-]+@(?:gmail|naver|daum|hanmail|kakao|nate|hotmail|outlook|icloud|yahoo)\.[a-z.]+")

FIREBASE_DB = re.compile(r"https://([a-z0-9\-]+)(?:-default-rtdb)?\.(?:firebaseio\.com|[a-z0-9\-]+\.firebasedatabase\.app)")
OLD_LIBS = [
    ("jQuery", re.compile(r"jquery[.\-/@]?v?(\d+\.\d+\.\d+)", re.I), (3, 5, 0), "3.5 미만은 알려진 XSS 취약점이 있어요(CVE-2020-11022). 최신 버전으로 올리세요"),
    ("Bootstrap", re.compile(r"bootstrap[.\-/@]?v?(\d+\.\d+\.\d+)", re.I), (3, 4, 1), "3.4.1 미만은 알려진 XSS 취약점이 있어요. 최신 버전으로 올리세요"),
    ("AngularJS", re.compile(r"angular(?:js)?[.\-/@]v?(1\.\d+\.\d+)", re.I), (2, 0, 0), "AngularJS 1.x는 2022년에 지원이 끝나 보안 패치가 없어요"),
    ("Lodash", re.compile(r"lodash[.\-/@]v?(\d+\.\d+\.\d+)", re.I), (4, 17, 21), "4.17.21 미만은 알려진 취약점이 있어요"),
]
THIRD_PARTY = {
    "googletagmanager.com": "구글 태그 관리자/애널리틱스", "google-analytics.com": "구글 애널리틱스",
    "connect.facebook.net": "메타 픽셀", "t1.kakaocdn.net": "카카오", "developers.kakao.com": "카카오",
    "cdn.channel.io": "채널톡", "wcs.naver.net": "네이버 애널리틱스", "static.hotjar.com": "핫자",
    "clarity.ms": "마이크로소프트 클래리티", "js.stripe.com": "스트라이프", "cdn.iamport.kr": "아임포트(포트원)",
    "js.tosspayments.com": "토스페이먼츠", "cdn.amplitude.com": "앰플리튜드", "cdn.mxpnl.com": "믹스패널",
}
INTERNAL = re.compile(r"(?:/Users/[A-Za-z0-9._\-]+|[A-Z]:\\\\Users\\\\|localhost:\d{2,5}|127\.0\.0\.1:\d{2,5}|staging\.[a-z0-9.\-]+|\.vercel\.app/preview)")
SOURCEMAP = re.compile(r"sourceMappingURL=([^\s'\"*]+\.map)")

COMMENT_HTML = re.compile(r"<!--(.*?)-->", re.S)
COMMENT_BLOCK = re.compile(r"/\*(?![!*])\s(.*?)\s\*/", re.S)          # /*! 라이선스 주석은 뺌
COMMENT_LINE = re.compile(r"(?<![:\"'=\\])//(?!/)\s*([^\n]{3,})")  # https:// 등은 뺌

MEMO_WORDS = re.compile(
    r"(?i)(\btodo\b|fixme|임시|테스트|지울 것|삭제할|나중에|대표님|사장님|실장|고객이|고객 요청|신청자|견적|단가|마진|원가 대비|비번|비밀번호|password|관리자 페이지|"
    r"요청하신|요청으로|프롬프트|chatgpt|claude|수정본|시안|\d차 수정|20\d\d-\d\d-\d\d)"
)
NORMAL_COMMENT = re.compile(r"(?i)^\s*(\[if |<!\[endif|google tag manager|end |/?(header|footer|nav|section|main)\b|#?\s*$)|litespeed|@license|copyright|generated by|page cached|minified|webflow|wordpress|wix|cafe24|imweb|framer")

CONFIG_PATHS = ["/.env", "/.env.local", "/.env.production", "/.git/HEAD", "/.git/config",
                "/netlify.toml", "/vercel.json", "/package.json", "/.DS_Store", "/wp-config.php.bak"]


def mask(s, keep=4):
    s = s.strip()
    return s[:keep] + "…" + "*" * 6 if len(s) > keep else "****"


def mask_phone(s):
    d = re.sub(r"\D", "", s)
    return f"{d[:3]}-{d[3:-4][:2]}**-****"


def jwt_role(token):
    try:
        payload = token.split(".")[1]
        payload += "=" * (-len(payload) % 4)
        data = json.loads(base64.urlsafe_b64decode(payload))
        return data.get("role") or data.get("type") or ""
    except Exception:
        return ""


class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links, self.assets = [], []

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "a" and a.get("href"):
            self.links.append(a["href"])
        elif tag == "script" and a.get("src"):
            self.assets.append(a["src"])
        elif tag == "link" and a.get("href") and ("stylesheet" in (a.get("rel") or "") or "modulepreload" in (a.get("rel") or "")):
            self.assets.append(a["href"])


LAST = {"headers": None, "url": None}


def fetch(url, method="GET", headers=None):
    req = urllib.request.Request(url, method=method, headers={"User-Agent": UA, **(headers or {})})
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT) as r:
            body = r.read(5_000_000) if method == "GET" else b""
            LAST["headers"], LAST["url"] = r.headers, r.geturl()
            return r.status, r.headers.get("Content-Type", ""), body.decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, "", ""
    except Exception as e:
        return 0, "", str(e)


def same_site(base, url):
    return urllib.parse.urlparse(base).netloc == urllib.parse.urlparse(url).netloc


# ---------- 점검 ----------
findings = []  # (등급, 위치, 무엇, 내용, 이유)
supabase = {"url": None, "keys": []}
firebase = set()
pages_html = {}


def add(level, where, what, content, why):
    key = (level, where, what, content)
    if key not in {(f[0], f[1], f[2], f[3]) for f in findings}:
        findings.append((level, where, what, content, why))


def line_of(text, idx):
    return text.count("\n", 0, idx) + 1


def scan_text(name, text):
    is_js = name.split("?")[0].endswith((".js", ".mjs", ".ts", ".tsx", ".jsx"))
    for label, pat in SECRET_PATTERNS:
        for m in pat.finditer(text):
            add("높음", f"{name}:{line_of(text, m.start())}", label, mask(m.group()),
                "누구나 복사해 쓸 수 있어요. 지우고, 발급한 곳에서 새 키로 바꿔야 해요")
    for m in PASSWORD.finditer(text):
        if not PASSWORD_FAKE.match(m.group(1)):
            add("확인", f"{name}:{line_of(text, m.start())}", "비밀번호처럼 보이는 값", mask(m.group(1), 2),
                "실제 비밀번호면 바로 바꾸고 코드에서 빼세요. 입력 칸 기본값이면 무시해도 돼요")
    for m in GOOGLE_KEY.finditer(text):
        add("확인", f"{name}:{line_of(text, m.start())}", "구글 API 키", mask(m.group()),
            "지도용 공개 키일 수 있어요. 구글 콘솔에서 웹사이트 제한(리퍼러)이 걸려 있는지 확인하세요")
    for m in SUPABASE_URL.finditer(text):
        supabase["url"] = m.group()
    for m in SUPABASE_NEWKEY.finditer(text):
        if m.group(1) == "secret":
            add("높음", f"{name}:{line_of(text, m.start())}", "Supabase secret 키", mask(m.group(), 10),
                "DB 잠금(RLS)을 무시하는 키예요. 바로 새로 발급하고 서버로 옮기세요")
        else:
            supabase["keys"].append(m.group())
    for m in JWT.finditer(text):
        role = jwt_role(m.group())
        if role == "service_role":
            add("높음", f"{name}:{line_of(text, m.start())}", "Supabase service_role 키", mask(m.group(), 8),
                "DB 잠금(RLS)을 무시하고 모든 데이터를 읽고 지울 수 있는 키예요. 바로 새로 발급하세요")
        elif role == "anon":
            supabase["keys"].append(m.group())
    for m in FIREBASE_DB.finditer(text):
        firebase.add(m.group(1))
    for lib, pat, bad, why in OLD_LIBS:
        for m in pat.finditer(text):
            v = tuple(int(x) for x in re.findall(r"\d+", m.group(1))[:3])
            if v and v < bad:
                add("중간", f"{name}:{line_of(text, m.start())}", "오래된 라이브러리", f"{lib} {m.group(1)}", why)
    for m in RRN.finditer(text):
        add("높음", f"{name}:{line_of(text, m.start())}", "주민번호 형식", m.group()[:6] + "-*******", "개인정보예요")
    spans = [(m.start(), m.end()) for p in (COMMENT_HTML, COMMENT_BLOCK) for m in p.finditer(text)]
    for m in PHONE.finditer(text):
        if PHONE_FAKE.search(m.group()):
            continue
        in_comment = any(s <= m.start() < e for s, e in spans)
        ctx = text[max(0, m.start() - 60):m.start()]
        if in_comment:
            add("높음", f"{name}:{line_of(text, m.start())}", "주석 속 휴대폰 번호", mask_phone(m.group()),
                "화면엔 안 보이는 메모에 남은 번호예요. 직원·고객 번호면 개인정보예요")
        elif is_js:
            add("중간", f"{name}:{line_of(text, m.start())}", "스크립트 속 휴대폰 번호", mask_phone(m.group()),
                "코드 안에 들어간 번호예요. 테스트·고객 데이터인지 확인하세요")
        elif re.search(r"(?i)tel:|telephone|\"phone\"\s*:|대표\s*번호|고객\s*센터|대표\s*전화|\b(tel|t|m|h\.?p)\s*[.:)]\s*$", ctx):
            add("확인", f"{name}:{line_of(text, m.start())}", "공개 연락처로 쓴 휴대폰", mask_phone(m.group()),
                "일부러 공개한 번호면 괜찮아요. 대표 개인 번호라면 회사 번호로 바꾸는 걸 권해요")
        else:
            add("확인", f"{name}:{line_of(text, m.start())}", "화면에 보이는 휴대폰 번호", mask_phone(m.group()),
                "공개용 연락처가 아니면 개인정보예요")
    for m in EMAIL.finditer(text):
        add("확인", f"{name}:{line_of(text, m.start())}", "개인 이메일", mask(m.group(), 3),
            "공개해도 되는 주소인지 확인하세요")
    for m in INTERNAL.finditer(text):
        add("낮음", f"{name}:{line_of(text, m.start())}", "내부 경로", m.group()[:40], "작업 컴퓨터·테스트 서버 흔적이에요")
    # 주석
    minified = any(len(l) > 500 for l in text.splitlines()[:50])
    pats = [COMMENT_HTML, COMMENT_BLOCK] + ([COMMENT_LINE] if not minified and (is_js or name.endswith((".html", ".htm", "/", ".ts", ".tsx", ".jsx"))) else [])
    for pat in pats:
        for m in pat.finditer(text):
            body = " ".join(m.group(1).split())
            if not body or NORMAL_COMMENT.search(body) or body.startswith(("{", "[", '"')):
                continue
            hit = MEMO_WORDS.search(body)
            if hit:
                shown = PHONE.sub(lambda x: mask_phone(x.group()), body)
                add("중간", f"{name}:{line_of(text, m.start())}", "작업 메모", shown[:70] + ("…" if len(shown) > 70 else ""),
                    f"'{hit.group()}' 같은 내부 내용이 소스에 보여요")
    for m in SOURCEMAP.finditer(text):
        supabase.setdefault("maps", []).append((name, m.group(1)))


def scan_url(start, own):
    pages, assets, seen = [start], [], set()
    for extra in ("/privacy", "/privacy-policy", "/policy/privacy"):
        pages.append(urllib.parse.urljoin(start, extra))
    s, _, sm = fetch(urllib.parse.urljoin(start, "/sitemap.xml"))
    if s == 200:
        for u in re.findall(r"<loc>\s*([^<\s]+)\s*</loc>", sm):
            if same_site(start, u) and u not in pages and not u.endswith(".xml"):
                pages.append(u)
    i = 0
    while i < len(pages) and i < MAX_PAGES:
        url = pages[i]; i += 1
        if url in seen:
            continue
        seen.add(url)
        status, ctype, body = fetch(url)
        if status != 200:
            if i == 1:
                print(f"첫 페이지를 못 받았어요 (상태 {status}). 주소를 확인해 주세요."); sys.exit(1)
            continue
        scan_text(urllib.parse.urlparse(url).path or "/", body)
        pages_html[urllib.parse.urlparse(url).path or "/"] = body
        if i == 1:
            first_headers, first_final = LAST["headers"], LAST["url"]
        p = LinkParser()
        try:
            p.feed(body)
        except Exception:
            pass
        for h in p.links:
            u = urllib.parse.urljoin(url, h).split("#")[0]
            if same_site(start, u) and u not in pages and not re.search(r"\.(png|jpe?g|gif|svg|webp|pdf|zip|mp4)$", u, re.I):
                pages.append(u)
        for h in p.assets:
            u = urllib.parse.urljoin(url, h)
            if same_site(start, u) and u not in assets:
                assets.append(u)
    for u in assets[:MAX_ASSETS]:
        status, _, body = fetch(u)
        if status == 200:
            scan_text(urllib.parse.urlparse(u).path, body)
    # 소스맵: JS가 가리키는 .map 파일이 열리면 원본 코드 전체가 공개된 것
    for name, mp in supabase.get("maps", []):
        base = urllib.parse.urljoin(start, name)
        mu = urllib.parse.urljoin(base, mp)
        status, _, body = fetch(mu)
        if status == 200 and '"sources"' in body:
            add("중간", name, "소스맵 공개", mp, "압축 전 원본 코드와 주석이 통째로 보여요. 배포 설정에서 소스맵을 끄세요")
            try:
                data = json.loads(body)
                for src, content in zip(data.get("sources", []), data.get("sourcesContent") or []):
                    if content:
                        scan_text(f"{mp} → {src}", content)
            except Exception:
                scan_text(mp, body)
    check_site(start, first_headers, first_final, assets)
    if own:
        check_own(start)
    return len(seen), min(len(assets), MAX_ASSETS)


def check_site(start, headers, final_url, assets):
    """누구나 받을 수 있는 응답 헤더와 HTML만으로 보는 항목."""
    h = {k.lower(): v for k, v in (headers.items() if headers else [])}
    https = (final_url or start).startswith("https://")
    if not https:
        add("높음", "/", "HTTPS 아님", final_url or start, "입력한 이름·번호가 암호화 없이 전송돼요. 호스팅에서 HTTPS를 켜세요")
    elif start.startswith("https://"):
        s, _, _ = fetch("http://" + start[len("https://"):])
        if s == 200 and LAST["url"] and LAST["url"].startswith("http://"):
            add("중간", "/", "HTTP로도 열림", "http:// 주소가 https로 넘어가지 않아요", "호스팅에서 HTTPS 강제 이동을 켜세요")
    need = [
        ("strict-transport-security", "HSTS 헤더 없음", "브라우저가 항상 HTTPS로만 접속하게 하는 설정이에요"),
        ("content-security-policy", "CSP 헤더 없음", "남의 스크립트가 끼어드는 공격(XSS)을 줄이는 설정이에요"),
        ("x-content-type-options", "X-Content-Type-Options 없음", "파일 종류를 속이는 공격을 막는 한 줄 설정이에요"),
        ("referrer-policy", "Referrer-Policy 없음", "다른 사이트로 넘어갈 때 주소에 든 정보가 따라가지 않게 해요"),
    ]
    if https:
        for k, what, why in need:
            if k not in h:
                add("낮음", "응답 헤더", what, "-", why)
        csp = h.get("content-security-policy", "")
        if "x-frame-options" not in h and "frame-ancestors" not in csp:
            add("낮음", "응답 헤더", "화면 끼워넣기 방지 없음", "X-Frame-Options / frame-ancestors", "내 사이트를 남의 사이트 안에 몰래 띄워 클릭을 유도하는 공격(클릭재킹)을 막아요")
    cookies = headers.get_all("Set-Cookie") if headers and hasattr(headers, "get_all") else []
    for c in cookies or []:
        name = c.split("=", 1)[0]
        low = c.lower()
        miss = [x for x, k in (("Secure", "secure"), ("HttpOnly", "httponly"), ("SameSite", "samesite")) if k not in low]
        if miss and re.search(r"(?i)sess|auth|token|login", name):
            add("중간", "쿠키", "로그인 쿠키 설정 부족", f"{name}: {', '.join(miss)} 없음", "쿠키를 가로채거나 스크립트로 읽을 수 있어요")
    # 페이지별: 혼합 콘텐츠, 폼 동의, 처리방침, 외부 스크립트
    has_policy = False
    collects_any = False
    for path, html in pages_html.items():
        low = html.lower()
        if https:
            for m in re.finditer(r"""(?:src|action)=["'](http://[^"']+)""", html):
                add("중간", f"{path}:{line_of(html, m.start())}", "혼합 콘텐츠", m.group(1)[:60], "HTTPS 페이지에서 암호화 안 된 주소를 불러요")
        if re.search(r"개인정보\s*처리\s*방침|privacy", low):
            has_policy = True
        korean = len(re.findall(r"[가-힣]", html)) > 50
        for fm in re.finditer(r"<form\b.*?</form>", html, re.S | re.I):
            f = fm.group(0) + html[fm.end():fm.end() + 800]
            auth_page = re.search(r"(?i)login|signin|sign-in|find-id|find-pw|reset|password|join|signup|register|회원가입|로그인", path)
            collects = korean and not auth_page and re.search(r"""(?i)(type=["']tel|name=["'][^"']*(phone|mobile|연락처|전화|휴대))""", fm.group(0))
            collects_any = collects_any or bool(collects)
            if collects and not re.search(r"개인정보.{0,40}(동의|수집)|(수집|이용).{0,20}동의|privacy|consent", f, re.I | re.S):
                add("높음", f"{path}:{line_of(html, fm.start())}", "동의 없는 개인정보 수집", "이름·연락처를 받는 폼에 수집·이용 동의 문구가 없어요",
                    "개인정보보호법 제15조: 수집 항목, 목적, 보유 기간, 거부 권리를 알리고 동의를 받아야 해요")
    if collects_any and not has_policy:
        add("중간", "전체 페이지", "개인정보 처리방침 링크 없음", "-", "개인정보보호법 제30조: 개인정보를 받는 사이트는 처리방침을 공개해야 해요")
    found = {}
    for u in assets + [m for html in pages_html.values() for m in re.findall(r"""src=["'](https?://[^"']+)""", html)]:
        host = urllib.parse.urlparse(u).netloc
        for dom, label in THIRD_PARTY.items():
            if host.endswith(dom):
                found[label] = dom
    for html in pages_html.values():
        for dom, label in THIRD_PARTY.items():
            if dom in html:
                found[label] = dom
    VENDOR = {"구글": r"google|구글", "메타": r"meta|facebook|메타|페이스북", "카카오": r"kakao|카카오", "채널톡": r"channel|채널톡|조이코퍼레이션",
              "네이버": r"naver|네이버", "핫자": r"hotjar|핫자", "마이크로소프트": r"microsoft|clarity|마이크로소프트", "스트라이프": r"stripe",
              "아임포트": r"portone|iamport|포트원|아임포트", "토스": r"toss|토스", "앰플리튜드": r"amplitude", "믹스패널": r"mixpanel"}
    policy_text = " ".join(re.sub(r"<[^>]+>", " ", h) for p, h in pages_html.items() if re.search(r"(?i)privacy|개인정보", p))
    missing = []
    for label in sorted(found):
        key = next((k for k in VENDOR if label.startswith(k)), None)
        if not policy_text or (key and not re.search(VENDOR[key], policy_text, re.I)):
            missing.append(label)
    if missing:
        add("중간" if collects_any else "참고", "처리방침", "처리방침에 없는 외부 서비스", ", ".join(missing),
            "방문자 정보를 받는 업체예요. 처리방침의 위탁·국외 이전 항목에 업체명·국가·항목을 적으세요")
    # robots.txt는 누구나 보는 파일
    s, _, body = fetch(urllib.parse.urljoin(start, "/robots.txt"))
    if s == 200:
        for m in re.finditer(r"(?im)^disallow:\s*(\S*(admin|manage|관리|dashboard|backup|private|internal)\S*)", body):
            if re.fullmatch(r"/?(wp-admin|admin|dashboard|manage|private)/?\*?", m.group(1), re.I):
                continue
            add("낮음", "/robots.txt", "숨기려는 주소가 공개됨", m.group(1), "robots.txt는 누구나 봐요. 관리자 주소는 여기 적지 말고 로그인으로 막으세요")


def check_own(start):
    root = "{0.scheme}://{0.netloc}".format(urllib.parse.urlparse(start))
    for p in CONFIG_PATHS:
        status, ctype, body = fetch(root + p)
        if status == 200 and body and "<html" not in body[:300].lower():
            add("높음", p, "설정 파일 공개", f"{p} 열림", "배포 폴더에서 빼고 다시 배포하세요")
    for proj in sorted(firebase):
        for base in (f"https://{proj}.firebaseio.com", f"https://{proj}-default-rtdb.firebaseio.com"):
            s, _, b = fetch(base + "/.json?shallow=true")
            if s == 200 and b.strip() not in ("null", ""):
                add("높음", base, "Firebase DB 로그인 없이 읽힘", "최상위 항목: " + ", ".join(list(json.loads(b))[:6]),
                    "Realtime Database 규칙이 공개로 열려 있어요. 규칙을 auth != null 이상으로 바꾸세요")
                break
    # Supabase: 공개 키(anon)로 로그인 없이 표가 읽히는지 (읽기만, 1줄만)
    if supabase["url"] and supabase["keys"]:
        key = supabase["keys"][0]
        h = {"apikey": key, "Authorization": f"Bearer {key}"}
        status, _, body = fetch(supabase["url"] + "/rest/v1/", headers=h)
        tables = []
        if status == 200:
            try:
                tables = [k.strip("/") for k in json.loads(body).get("paths", {}) if k.count("/") == 1 and k != "/"]
            except Exception:
                pass
        for t in tables[:30]:
            s, _, b = fetch(f"{supabase['url']}/rest/v1/{t}?select=*&limit=1", headers=h)
            if s == 200 and b.strip() not in ("", "[]"):
                try:
                    cols = ", ".join(list(json.loads(b)[0].keys())[:6])
                except Exception:
                    cols = ""
                add("높음", f"Supabase 표 '{t}'", "로그인 없이 읽힘", f"열: {cols}",
                    "누구나 이 표를 내려받을 수 있어요. 이 표에 RLS를 켜고 정책을 만드세요")


def scan_folder(folder):
    n = 0
    for dp, dn, fn in os.walk(folder):
        dn[:] = [d for d in dn if d not in ("node_modules", ".git", "원본-백업")]
        for f in fn:
            if f.endswith((".html", ".htm", ".css", ".js", ".mjs", ".map", ".json")):
                path = os.path.join(dp, f)
                with open(path, encoding="utf-8", errors="replace") as fh:
                    scan_text(os.path.relpath(path, folder), fh.read())
                n += 1
    return n


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    own = "--own" in sys.argv
    if not args:
        print(__doc__); sys.exit(1)
    target = args[0]
    if re.match(r"https?://", target) or "." in target and not os.path.exists(target):
        if not target.startswith("http"):
            target = "https://" + target
        pages, assets = scan_url(target, own)
        scope = f"페이지 {pages}, 에셋 {assets}"
    else:
        scope = f"파일 {scan_folder(target)}"
    order = {"높음": 0, "중간": 1, "확인": 2, "낮음": 3, "참고": 4}
    def loc(w):
        m = re.match(r"(.*):(\d+)$", w)
        return (m.group(1), int(m.group(2))) if m else (w, 0)
    findings.sort(key=lambda f: (order[f[0]], loc(f[1])))
    high = sum(f[0] == "높음" for f in findings)
    mid = sum(f[0] in ("중간", "확인") for f in findings)
    print(f"점검 대상: {target} ({scope}{', --own 포함' if own else ''})")
    print(f"High {high} · Medium {mid} · Low/Info {len(findings) - high - mid}\n")
    if not findings:
        print("페이지 소스에서 찾은 게 없어요. DB 권한은 소스만으로 알 수 없으니 --own 점검이나 개발자 확인을 따로 하세요.")
        return
    print("| 심각도 | 위치 | 항목 | 증거 | 영향·조치 |\n|---|---|---|---|---|")
    for lv, where, what, content, why in findings:
        print(f"| {lv} | {where} | {what} | {content.replace('|', '/')} | {why} |")
    if supabase["keys"] and not own:
        print("\nSupabase 공개 키(anon)가 보여요. 이 키 자체는 공개해도 되는 키지만, 표마다 RLS가 꺼져 있으면 이 키로 고객 데이터를 누구나 읽어요. 내 사이트면 --own 으로 다시 돌려 확인하세요.")


if __name__ == "__main__":
    main()
